        "modeLabel": "勿扰模式",
        "modeState": "点击切换"
      },
      "data": {
        "calendar": {
          "items": [
            {
              "entityName": "calendar",
              "entityId": "low-power-018-meeting",
              "title": "会议",
              "dtStart": "10:00",
              "dtEnd": "11:00"
            },
            {
              "entityName": "calendar",
              "entityId": "low-power-018-lunch",
              "title": "午饭",
              "dtStart": "14:00",
              "dtEnd": "15:00"
            }
          ]
        }
      },
      "asset": {
        "powerIcon": "resources/base/media/icon_charge.png"
      },
      "state": {
        "loading": false
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "charge_icon",
      "src": "resources/base/media/icon_charge.png",
      "use": "low power warning icon",
      "description": "充电图标，适合低电量提醒和电量不足主视觉。",
      "bindTo": "/asset/powerIcon",
      "static": true
    }
  ]
}

